"""`Gag`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'Gag'


def build(lib):
    t = lib.new_material(NAME, props={})

    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (600.0, 0.0),
    })
    t.node('ShaderNodeGroup', 'gag.output', props={
        'node_tree': lib.group('.Gag output'),
        'location': (350.0, 0.0),
        'label': 'gag.output',
    })
    # The frame, from a property each object with this material gets (`steps/gag.py`, ADR 0042): a
    # driver here would update the material on every frame.
    t.node('ShaderNodeAttribute', 'gag.frame', props={
        'location': (-900.0, 200.0),
        'label': 'gag.frame',
        'attribute_type': 'OBJECT',
        'attribute_name': 'kkbp_gag_frame',
    })
    t.node('ShaderNodeValue', 'gag.choice', props={
        'location': (-900.0, 0.0),
        'label': 'gag.choice',
    })

    t.link('gag.output', 'Shader', 'Material Output', 'Surface')
    return t
